#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long t;
    cin >> n >> t;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long lo = 1, hi = 1;
    for (int i = 0; i < n; i++) hi = max(hi, a[i]);
    while (lo < hi) {
        long long mid = (lo + hi) / 2;
        long long total = 0;
        for (int i = 0; i < n; i++) total += (a[i] + mid - 1) / mid;
        if (total <= t) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << "\n";

    return 0;
}

